import { PlaceholderImageSVG } from "./placeholder-image";
import { reactDeclaration, rewriteImageUrl } from "./util";

export const ChatImageDeclaration = reactDeclaration({
    type: "image",
    name: "Image",
    schema: `{
    src: string;
    maxHeight?: string;
    style?: React.CSSProperties;
}`,
    renderPreview: props => {
        return <ChatImage src={<PlaceholderImageSVG />} {...props} />;
    },
    render: props => {
        return <ChatImage src={<PlaceholderImageSVG />} {...props} />;
    },
});

export const ChatImage = ({
    src,
    maxHeight,
    style,
}: {
    src: string | React.ReactNode;
    maxHeight?: string;
    style?: React.CSSProperties;
}) => {
    if (typeof src === "string") {
        return (
            <img
                style={{
                    maxWidth: "100%",
                    maxHeight,
                    height: "100%",
                    objectFit: "cover",
                    ...style,
                }}
                src={src.startsWith("http") ? rewriteImageUrl(src) : src}
            />
        );
    }
    return src;
};
